\label{defaf}
A complete three manifold $(M,g)$ is said to be {\rm asymptotically flat}
(AF) of order $\tau$ (with one end) if there is a compact subset $K$
such that $M\setminus K$ is diffeomorphic to $\Bbb R^3\setminus B_R(0)$
for some $R>0$ and in the standard coordinates in $\Bbb R^3$, the metric
$g$ satisfies:
\begin{equation} \label{daf1}
g_{ij}=\delta_{ij}+\sigma_{ij}
\end{equation}
with
\begin{equation} \label{daf2}
|\sigma_{ij}|+r|\partial \sigma_{ij}|+r^2|\partial\partial\sigma_{ij}|=O(r^{-\tau}),
\end{equation}
for some constant $1\ge\tau>\frac{1}{2}$, where $r$ and $\partial$ denote
the Euclidean distance and standard derivative operator on $\Bbb R^3$
respectively.

The Arnowitt-Deser-Misner (ADM) mass (see \cite{ADM}) of an
asymptotically flat manifold $M$ is defined as:
\begin{equation} \label{defadm1}
m_{ADM}(M)=\lim_{r\to\infty}\frac{1}{16\pi}\int_{S_r}
\left(g_{ij,i}-g_{ii,j}\right)\nu^jd\sigma^0,
\end{equation}
where $S_r$ is the Euclidean sphere, $d\sigma^0$ is the volume
element induced by the Euclidean metric, $\nu$ is the outward unit
normal of $S_r$ in $\Bbb R^3$ and the derivative is the ordinary
partial derivative.

\label{estimate of area}
Let $\Sigma_r$ be  nearly round  surfaces in $(M, g)$  when $r$ goes to
infinity, then there is a positive constant $\Lambda$ which is
independent of $r$, and with $\Lambda^{-1} r^2 \leq {\rm Area}
(\Sigma_r)\leq \Lambda r^2$.

Let $\hat \nabla$ be the covariant derivatives with
respect to $\hat g$, then by a direct computation gives
\begin{equation}
\begin{split}
\frac{\partial^2 \rho}{\partial x^i \partial x^j}& =\hat \nabla^2 \rho
((\frac{\partial}{\partial
x^i})^T, (\frac{\partial}{\partial x^j})^T )\\
&=\hat A ((\frac{\partial}{\partial x^i})^T, (\frac{\partial}{\partial x^j})^T )\\
&=\overset{\circ}{\hat A}((\frac{\partial}{\partial x^i})^T, (\frac{\partial}{\partial
x^j})^T ) +\frac{\hat H}{2}h_{ij}.
\end{split}
\end{equation}

\label{difference of mean curvature}
Let $\rho$ be the Euclidean distance to $\Sigma_r$ in $\Bbb R^3$, then
\begin{equation}\label{meancuravture}
\begin{split}
H=&\hat H +\frac{H}{2}\sigma_{ij}\frac{\partial \rho}{\partial x^i}\frac{\partial
\rho}{\partial x^j}+\frac12 \sigma_{st,i}\frac{\partial \rho}{\partial x^i}\frac{\partial
\rho}{\partial x^s}\frac{\partial \rho}{\partial x^t}\\
&-\sigma_{ij}\frac{\partial^2 \rho}{\partial x^i \partial x^j}-g_{ij,i}\frac{\partial
\rho}{\partial x^j}
+\frac12 g_{jj,i}\frac{\partial \rho}{\partial x^i}+O(r^{-1-2\tau}).\\
\end{split}
\end{equation}
Here and in the sequel, $\sigma_{ij,k}=\frac{\partial \sigma_{ij}}{\partial
x^k}$ and $g_{ij,k}=\frac{\partial g_{ij}}{\partial x^k}$.

\label{estimate H0}
Let $\Sigma_r\subset (M, g)$ be a nearly round  surfaces in $(M,g)$ as
$r$ goes to infinity,  and $r_0$  defined as in Proposition
\ref{nearround}. Then there is isometrically embedding $X_{r}$ of
$\Sigma_r$ into $\mathbb{R}^3$ such that
\begin{equation}\label{suppfun}
X_{r}\cdot n_0 =r_0 +O(r_0 ^{1-\tau})
\end{equation}
and
\begin{equation}\label{meancurvexp}
\|H_0  -\frac{2}{r_0}\|_{C^0}\leq C_3 r_0 ^{-1-\tau },
\end{equation}
provided that $r_0$ is  large enough. Here $n_0$ and $H_0 $ are the
unit outward normal vector and mean curvature of $X_r (\Sigma_r)$ in
$\mathbb{R}^3$ respectively. $C_3$ is a constant that is independent
of $r$.
